// Shared, deterministic learning rules. These are app estimates, not a standardized test.
export const LEARNING_MODEL='12.0.0';
// A model sentence is useful practice, but is not independent productive use.
export function copiedUsageExample(answer,examples=[]){
 const clean=s=>String(s||'').normalize('NFKC').replace(/[\s\p{P}\p{S}]/gu,'').toLowerCase();
 const a=clean(answer);if(!a)return false;
 return examples.some(example=>{
  const b=clean(example);if(!b)return false;if(a===b)return true;
  if(Math.min(a.length,b.length)<12||Math.min(a.length,b.length)/Math.max(a.length,b.length)<.92)return false;
  const grams=s=>new Set(Array.from({length:s.length-1},(_,i)=>s.slice(i,i+2))),x=grams(a),y=grams(b);
  const overlap=[...x].filter(g=>y.has(g)).length;
  return overlap/Math.max(x.size,y.size)>=.92;
 });
}
