export const INDEPENDENT_MULTIWORD_TARGETS=['탄소 중립','먹이 사슬','발이 넓다','손이 크다','발을 빼다','귀가 얇다','눈이 높다','입이 무겁다','입이 가볍다'];
const independentMultiwordKeys=new Set(INDEPENDENT_MULTIWORD_TARGETS.map(w=>w.replace(/\s+/gu,'')));
export function isContextOnlyExpression(word){
 const text=String(word||'').normalize('NFKC').trim(),key=text.replace(/\s+/gu,'');
 if(contextOnlyKeys.has(key)||['근거자료','공공재원','공공임대주택','여론조작'].includes(key))return true;
 if(independentMultiwordKeys.has(key))return false;
 return /\s/u.test(text)||/^[가-힣]{2,}적(?:장치|기제|표현|의미|관점|판단|사고|근거|반응|태도|행동|변화|영향|효과|요인|배경|상황|문제|관계|구조|특징|가치|책임|정당성|맥락|기능|원칙|방식|과정|방법|목표|수단|연결|수용|연결망)$/u.test(key);
}
