export function isRecordedVocabulary(word,domain='',band=0){const row=word&&typeof word==='object'?word:null,text=String(row?.w||row?.word||word||'').normalize('NFKC').trim(),key=text.replace(/\s+/gu,'');domain=ESSENTIAL_VOCABULARY[text]?.cat||row?.cat||row?.domain||domain;band=ESSENTIAL_VOCABULARY[text]?.band??Number(row?.band??band);return !!text&&!isContextOnlyExpression(text)&&!specialistKeys.has(key)&&(!/수학/.test(domain)||generalReasoningKeys.has(key))&&(!(domain==='과학'&&Number(band)>=6)||generalScienceKeys.has(key))}
