export function vocabularyBand(word){return ESSENTIAL_VOCABULARY[word?.w||word?.word]?.band??CALIBRATED_BANDS[word?.w||word?.word]??Number(word?.band||3)}
export function calibratedWord(word){
 const band=vocabularyBand(word),e=ESSENTIAL_VOCABULARY[String(word?.w||word?.word||'')];
 if(!e)return band===Number(word.band)?word:{...word,band};
 const fields=word.w?{d:e.d,cat:e.cat}:{definition:e.d,domain:e.cat};
 return band===Number(word.band)&&Object.entries(fields).every(([k,v])=>word[k]===v)?word:{...word,...fields,band};
}

export function targetBandRange(level){const n=Math.max(1,Math.min(9,Number(level)||2));return {min:Math.max(1,Math.ceil(n-1)),max:Math.min(9,Math.floor(n+1))}}
export function inTargetBand(word,level){const r=targetBandRange(level);return vocabularyBand(word)>=r.min&&vocabularyBand(word)<=r.max}
export function reviewFloor(level){return targetBandRange(level).min}
