function finishRealtimeLevels(learner,active,day,lessonId){
 const a=active.adaptation,history=Array.isArray(learner.levelAdjustmentHistory)?learner.levelAdjustmentHistory:[];
 const duplicate=lessonId&&history.find(x=>x.lessonId===lessonId);if(duplicate)return duplicate;
 const from=a.startLeague,to=levelNumber(learner.difficulty),change=Math.round((to-from)*10)/10;
 const adjustment={policy:REALTIME_LEVEL_POLICY,lessonId,date:day,from,to,change,score:a.estimate,
  samples:a.rows.length,uniqueWords:a.rows.length,productiveWords:a.rows.filter(r=>r.productive).length,
  total:(active.results||[]).filter(r=>!r.excludedFromVocabulary&&isLearningTarget(r.word)).length,
  checks:a.events.map(e=>({...e})),reason:change?'학습 중 확인한 어휘 수준을 순위 등급에도 반영했어요.':'이번 회차에서 확인한 수준을 유지했어요.'};
 learner.leagueLevel=to;learner.lastLevelAdjustment=adjustment;
 if(lessonId)learner.levelAdjustmentHistory=[...history,adjustment].slice(-60);
 return adjustment;
}
export function reconcileLevelBackfill(remote,local){
 if(!remote.gradeBackfill?.id||remote.gradeBackfill.id===local.gradeBackfill?.id)return local;
 const history=[...(remote.levelAdjustmentHistory||[])],known=new Set(history.map(x=>x.lessonId));
 let grade=remote.difficulty,last=remote.lastLevelAdjustment;
 for(const a of local.levelAdjustmentHistory||[]){
  if(![REALTIME_LEVEL_POLICY,SESSION_LEVEL_POLICY,'session-performance-12.11'].includes(a.policy)||!a.lessonId||known.has(a.lessonId)||a.date<remote.gradeBackfill.date||!Number.isFinite(a.change)||Math.abs(a.change)>(a.policy===REALTIME_LEVEL_POLICY?8:.2))continue;
  const next=Math.round(Math.max(1,Math.min(9,grade+a.change))*10)/10;
  last={...a,from:grade,to:next,change:Math.round((next-grade)*10)/10,reason:'소급 반영된 등급에 이 회차의 변화를 이어서 적용했어요.'};
  history.push(last);known.add(a.lessonId);grade=next;
 }
 const byId=new Map(history.map(x=>[x.lessonId,x]));
 const key=s=>JSON.stringify([s.date,s.mode,s.score,s.total,s.good,s.wrong,s.activeMinutes]);
 const previous=new Map((remote.sessions||[]).map(s=>[key(s),s.levelAdjustment]));
 const sessions=(local.sessions||[]).map(s=>{const a=byId.get(s.levelAdjustment?.lessonId)||previous.get(key(s));return a?{...s,levelAdjustment:a}:s});
 return {...local,sessions,difficulty:grade,leagueLevel:grade,gradeBackfill:remote.gradeBackfill,lastLevelAdjustment:last,levelAdjustmentHistory:history.slice(-60)};
}
export function updateLearningLevels(learner,results,day=learningDay(),options={}){
 if(options.active?.adaptation?.policy===REALTIME_LEVEL_POLICY)return finishRealtimeLevels(learner,options.active,day,options.lessonId||options.active.lessonId);
 const lessonId=options.lessonId||null;
 const history=Array.isArray(learner.levelAdjustmentHistory)?learner.levelAdjustmentHistory:[];
 const duplicate=lessonId&&history.find(x=>x.lessonId===lessonId);
 if(duplicate)return duplicate;
 const previous=Math.round(Math.max(1,Math.min(9,Number(learner.difficulty)||2))*10)/10;
 const range=targetBandRange(previous);
 const rows=(results||[]).filter(r=>!r.excludedFromVocabulary&&!r.remedial&&isLearningTarget(r.word)&&Number.isFinite(Number(r.band))&&vocabularyBand({w:r.word,band:r.band})>=range.min&&vocabularyBand({w:r.word,band:r.band})<=range.max);
 const creditFor=r=>{
  let credit=Number.isFinite(r.credit)?r.credit:r.result==='◎'||r.result==='○'?1:r.result==='△'?.5:r.result==='?'?.25:0;
  if(r.revealed)credit=0;
  if(r.hintUsed)credit=Math.min(.75,credit);
  return Math.max(0,Math.min(1,credit));
 };
 // Each vocabulary item contributes equally; repeats of the same task type
 // cannot outvote other words or replace its first attempt with feedback practice.
 const byWord=new Map();
 for(const r of rows){
  if(!byWord.has(r.word))byWord.set(r.word,new Map());
  const types=byWord.get(r.word),type=r.type||'unknown';
  if(!types.has(type))types.set(type,r);
 }
 const uniqueWords=byWord.size;
 const wordScores=[...byWord.values()].map(types=>[...types.values()].reduce((sum,r)=>sum+creditFor(r),0)/types.size);
 const score=uniqueWords?Math.round(wordScores.reduce((sum,n)=>sum+n,0)/uniqueWords*100):null;
 const productiveWords=[...byWord.values()].filter(types=>[...types.values()].some(r=>r.type?.startsWith('subjective_')&&creditFor(r)>=.8&&!r.hintUsed&&!r.revealed)).length;
 const performanceChange=score==null?0:score>=90?.2:score>=80?.1:score>=60?0:score>=40?-.1:-.2;
 const insufficientBreadth=uniqueWords<3;
 const insufficientProduction=performanceChange>0&&productiveWords<2;
 const fullChange=insufficientBreadth||insufficientProduction?0:performanceChange;
 // A short, unfinished lesson contributes less than the standard 20 activities.
 const requested=Math.round(fullChange*Math.min(1,rows.length/20)*10)/10;
 const next=Math.round(Math.max(1,Math.min(9,previous+requested))*10)/10;
 const adjustment={policy:SESSION_LEVEL_POLICY,lessonId,date:day,samples:rows.length,uniqueWords,productiveWords,total:(results||[]).filter(r=>!r.excludedFromVocabulary&&isLearningTarget(r.word)).length,score,from:previous,to:next,change:Math.round((next-previous)*10)/10,
  reason:!rows.length?'이번 수준에 맞는 평가 문항이 없어 등급을 유지했어요.':insufficientBreadth?'등급 판단에 필요한 서로 다른 어휘 3개가 모이지 않아 등급을 유지했어요.':insufficientProduction?'선택 정답에 더해 서로 다른 어휘 2개의 주관식 이해·사용을 확인하면 등급이 오를 수 있어요.':next===previous&&requested!==0?'등급 범위 1.0~9.0 안에서 유지했어요.':next===previous&&fullChange!==0?'짧게 마친 회차의 활동 수를 반영해 등급을 유지했어요.':next>previous?'이번 회차의 뜻과 쓰임 이해가 좋아 등급이 올랐어요.':next<previous?'이번 회차에서 어려웠던 어휘를 더 연습하도록 등급을 낮췄어요.':'이번 회차의 성과에 맞춰 등급을 유지했어요.'};
 // Same-day practice affects this game estimate, while delayed recall and
 // mastery evidence keep their separate requirements above.
 learner.difficulty=next;learner.leagueLevel=next;
 learner.lastLevelAdjustment=adjustment;
 if(lessonId)learner.levelAdjustmentHistory=[...history,adjustment].slice(-60);
 return adjustment;
}

export function summarizeEvidence(learner){
 const entries=(learner.learningEvidence||[]).filter(x=>isLearningTarget(x.word));
 const stat=filter=>{const xs=entries.filter(filter);return {attempts:xs.length,success:xs.filter(x=>x.success).length,percent:xs.length?Math.round(xs.filter(x=>x.success).length/xs.length*100):null}};
 return {recognition:stat(x=>x.kind==='recognition'&&x.firstAttempt),recall:stat(x=>x.kind==='recall'&&x.firstAttempt&&x.lagDays>=1),use:stat(x=>x.kind==='use'),transfer:stat(x=>x.kind==='transfer'&&x.firstAttempt),retention7:stat(x=>x.kind==='recall'&&x.firstAttempt&&x.lagDays>=7&&x.lagDays<30),retention30:stat(x=>x.kind==='recall'&&x.firstAttempt&&x.lagDays>=30),mastered:Object.entries(learner.words||{}).filter(([w,s])=>isLearningTarget(w)&&masteryConfirmed(s)).length};
}

// Display-only migration: keep stored lesson IDs, order, questions and prior answers
// intact. Existing validated word definitions replace ambiguous written blanks.
export function sentenceWritingTask(word){const code=String(word).at(-1)?.charCodeAt(0),particle=code>=0xac00&&code<=0xd7a3&&(code-0xac00)%28?'을':'를';return {prompt:'‘'+word+'’'+particle+' 넣어 뜻이 드러나는 문장 하나를 만들어 보세요.',context:'',hints:['이 단어가 필요한 일을 직접 떠올려 보세요.','문장을 읽고 이 단어의 뜻이 알맞게 쓰였는지 확인해 보세요.']}}
export function presentWrittenQuestion(question){
 if(question?.type==='subjective_use'){
  const task=sentenceWritingTask(question.w?.w||'');
  return {...question,w:calibratedWord(question.w),q:task.prompt,ctx:'',hints:task.hints,opts:[],acceptedAnswers:[],showTarget:true,hideWord:false,open:true,writtenFormat:'own-sentence-12.13'};
 }
 if(!['subjective_context','subjective_dialogue'].includes(question?.type))return question;
 const word=question.w?.w||'',definition=String(question.w?.d||'').trim();
 const safeDefinition=definition&&!definition.includes(word);
 if(!word)return question;
 if(!safeDefinition)return {...question,type:'subjective_use',label:LEARNING_LABELS.subjective_use,showTarget:true,hideWord:false,open:true,
  q:sentenceWritingTask(word).prompt,ctx:'',opts:[],acceptedAnswers:[],
  hints:['누가 무엇을 했는지 떠올려 보세요.','이 단어가 필요한 상황을 한 문장으로 표현해 보세요.'],feedbackCorrect:'이 단어를 알맞게 사용한 다양한 문장을 인정해요.',writtenFormat:'meaning-use-12.12'};
 const scene=String(question.ctx||'').split(/(?<=[.!?。])\s*|\n/).find(line=>line.trim()&&!/＿|_{2,}|□|빈칸/.test(line)&&!line.includes(word))||'';
 return {...question,type:'subjective_recall',label:LEARNING_LABELS.subjective_recall,showTarget:false,hideWord:true,open:true,
  q:'설명을 읽고, 이 뜻에 해당하는 단어를 써 보세요.',ctx:[scene, '뜻 설명: '+definition].filter(Boolean).join('\n'),opts:[],answerForm:word,
  acceptedAnswers:[{text:word,credit:1,rationale:'설명에 해당하는 목표 어휘'}],
  hints:['설명에서 중요한 뜻을 찾아보세요.','비슷한 말과 구별되는 뜻까지 담은 단어를 떠올려 보세요.'],
  feedbackCorrect:word+' · '+definition,writtenFormat:'meaning-use-12.12'};
}



